        isFlying = false;
        altitude = 0;
        System.out.println("The airplane has landed.");
    }

    public void increaseAltitude(double meters) {
        if (isFlying) {
            altitude += meters;
            System.out.println("The airplane has increased its altitude by " + meters + " meters.");
        } else {
            System.out.println("The airplane needs to take off first.");
        }
    }

    public void decreaseAltitude(double meters) {
        if (isFlying) {
            altitude -= meters;
            System.out.println("The airplane has decreased its altitude by " + meters + " meters.");
        } else {
            System.out.println("The airplane needs to take off first.");
        }
    }

    // Implement any other methods specific to the Airplane class
    // ...
}
